for k, v in RAW["u"].items():
    g, t = k.split("|")
    u[g, int(t)] = int(round(v))
for k, v in RAW["p"].items():
    g, t = k.split("|")
    p[g, int(t)] = float(v)
for k, v in RAW["r"].items():
    g, t = k.split("|")
    r[g, int(t)] = float(v)
for k, v in RAW["rp"].items():
    g, t = k.split("|")
    rp[g, int(t)] = float(v)

errors = []
TOL = 1e-4

def startup_shutdown(g):
    on0 = TH[g]["unit_on_t0"]
    su, sd_ = [], []
    prev = on0
    for t in range(T):
        su.append(1 if (u[g, t] == 1 and prev == 0) else 0)
        sd_.append(1 if (u[g, t] == 0 and prev == 1) else 0)
        prev = u[g, t]
    return su, sd_

def downtime_before(g, t):
    """consecutive off hours immediately before hour t (looking into t0 state)"""
    G = TH[g]
    if t == 0:
        return G["time_down_t0"] if G["unit_on_t0"] == 0 else 0
    d = 0
    for i in range(t - 1, -1, -1):
        if u[g, i] == 0:
            d += 1
        else:
            break
    else:
        if G["unit_on_t0"] == 0:
            d += G["time_down_t0"]
    return d

def startup_cost(G, t):
    """cost tier for a startup at hour t given downtime"""
    dt = downtime_before(G["name"], t) if "name" in G else None
    return dt

def tier_cost(G, downtime):
    tiers = G["startup"]
    applicable = [st for st in tiers if st["lag"] <= downtime]
    if not applicable:
        return tiers[0]["cost"]
    return applicable[-1]["cost"]

def unit_hour_cost(G, mw):
    pw = G["piecewise_production"]
    if mw <= pw[0]["mw"] + TOL:
        return pw[0]["cost"]
    tot = pw[0]["cost"]
    for i in range(len(pw) - 1):
        if mw >= pw[i + 1]["mw"] - TOL:
            tot += pw[i + 1]["cost"] - pw[i]["cost"]
        else:
            frac = (mw - pw[i]["mw"]) / (pw[i + 1]["mw"] - pw[i]["mw"])
            tot += frac * (pw[i + 1]["cost"] - pw[i]["cost"])
            break
    return tot

