CASE = json.load(open("network.json"))
REP = json.load(open("report.json"))
T = CASE["time_periods"]
TH = CASE["thermal_generators"]
REN = CASE["renewable_generators"]
DEMAND = CASE["demand"]
RESERVES = CASE["reserves"]
fails = []
TOL = 1e-3

# structure
assert REP["case_name"] == "unit_commitment_schedule"
assert len(REP["thermal_generators"]) == len(TH) == REP["summary"]["num_thermal_generators"]
assert len(REP["renewable_generators"]) == len(REN) == REP["summary"]["num_renewable_generators"]
tset = {g["name"] for g in REP["thermal_generators"]}
rset = {g["name"] for g in REP["renewable_generators"]}
assert tset == set(TH.keys()) and rset == set(REN.keys())
for g in REP["thermal_generators"]:
    assert len(g["commitment"]) == len(g["production_MW"]) == len(g["reserve_MW"]) == len(g["startup"]) == len(g["shutdown"]) == T
for g in REP["renewable_generators"]:
    assert len(g["production_MW"]) == T
assert len(REP["hourly_summary"]) == T
assert [h["hour"] for h in REP["hourly_summary"]] == list(range(1, T + 1))

# per-unit checks
total_cost = 0.0
n_start = n_stop = 0
for g in REP["thermal_generators"]:
    G = TH[g["name"]]
    pmin, pmax = G["power_output_minimum"], G["power_output_maximum"]
    ru, rd = G["ramp_up_limit"], G["ramp_down_limit"]
    su, sdn = G["ramp_startup_limit"], G["ramp_shutdown_limit"]
    utm, dtm = G["time_up_minimum"], G["time_down_minimum"]
    on0, p0 = G["unit_on_t0"], G["power_output_t0"]
    up0, dn0 = G["time_up_t0"], G["time_down_t0"]
    c, p = g["commitment"], g["production_MW"]
    rv, st, sp = g["reserve_MW"], g["startup"], g["shutdown"]
    if G["must_run"] == 1:
        if any(x != 1 for x in c):
