#!/usr/bin/env python3
"""Verify raw UC solution against all constraints and write ./report.json"""
import json

CASE = json.load(open("network.json"))
RAW = json.load(open("solution_raw.json"))
T = CASE["time_periods"]
TH = CASE["thermal_generators"]
REN = CASE["renewable_generators"]
DEMAND = CASE["demand"]
RESERVES = CASE["reserves"]
tnames = list(TH.keys())
rnames = list(REN.keys())

u = {}
p = {}
r = {}
rp = {}
for k, v in RAW["u"].items():
    g, t = k.split("|")
    u[g, int(t)] = int(round(v))
for k, v in RAW["p"].items():
    g, t = k.split("|")
    p[g, int(t)] = float(v)
for k, v in RAW["r"].items():
    g, t = k.split("|")
    r[g, int(t)] = float(v)
for k, v in RAW["rp"].items():
    g, t = k.split("|")
    rp[g, int(t)] = float(v)

errors = []
TOL = 1e-4

def startup_shutdown(g):
    on0 = TH[g]["unit_on_t0"]
    su, sd_ = [], []
    prev = on0
    for t in range(T):
        su.append(1 if (u[g, t] == 1 and prev == 0) else 0)
        sd_.append(1 if (u[g, t] == 0 and prev == 1) else 0)
        prev = u[g, t]
    return su, sd_

def downtime_before(g, t):
    """consecutive off hours immediately before hour t (looking into t0 state)"""
    G = TH[g]
    if t == 0:
        return G["time_down_t0"] if G["unit_on_t0"] == 0 else 0
    d = 0
    for i in range(t - 1, -1, -1):
        if u[g, i] == 0:
            d += 1
        else:
            break
    else:
        if G["unit_on_t0"] == 0:
            d += G["time_down_t0"]
    return d

def startup_cost(G, t):
    """cost tier for a startup at hour t given downtime"""
    dt = downtime_before(G["name"], t) if "name" in G else None
    return dt

def tier_cost(G, downtime):
    tiers = G["startup"]
    applicable = [st for st in tiers if st["lag"] <= downtime]
    if not applicable:
        return tiers[0]["cost"]
    return applicable[-1]["cost"]

def unit_hour_cost(G, mw):
    pw = G["piecewise_production"]
    if mw <= pw[0]["mw"] + TOL:
        return pw[0]["cost"]
    tot = pw[0]["cost"]
    for i in range(len(pw) - 1):
        if mw >= pw[i + 1]["mw"] - TOL:
            tot += pw[i + 1]["cost"] - pw[i]["cost"]
        else:
            frac = (mw - pw[i]["mw"]) / (pw[i + 1]["mw"] - pw[i]["mw"])
            tot += frac * (pw[i + 1]["cost"] - pw[i]["cost"])
            break
    return tot

# ---------- independent constraint verification ----------
max_bal_viol = 0.0
max_res_short = 0.0
prod_cost = 0.0
startups_total = 0
shutdowns_total = 0
startup_cost_total = 0.0

for t in range(T):
    gen = sum(p[g, t] for g in tnames) + sum(rp[n, t] for n in rnames)
    max_bal_viol = max(max_bal_viol, abs(gen - DEMAND[t]))
    res = sum(r[g, t] for g in tnames)
    max_res_short = max(max_res_short, max(0.0, RESERVES[t] - res))

for g in tnames:
    G = TH[g]
    pmin, pmax = G["power_output_minimum"], G["power_output_maximum"]
    ru, rd = G["ramp_up_limit"], G["ramp_down_limit"]
    su, sdn = G["ramp_startup_limit"], G["ramp_shutdown_limit"]
    utm, dtm = G["time_up_minimum"], G["time_down_minimum"]
    on0, p0 = G["unit_on_t0"], G["power_output_t0"]
    up0, dn0 = G["time_up_t0"], G["time_down_t0"]
    su_ind, sd_ind = startup_shutdown(g)
    startups_total += sum(su_ind)
    shutdowns_total += sum(sd_ind)

    # must run
    if G["must_run"] == 1:
        for t in range(T):
            if u[g, t] != 1:
                errors.append(f"must_run violated {g} t{t}")
    # generator limits
    for t in range(T):
        if u[g, t] == 1:
            if not (pmin - TOL <= p[g, t] <= pmax + TOL):
                errors.append(f"limits {g} t{t} p={p[g,t]}")
            prod_cost += unit_hour_cost(G, p[g, t])
            # reserve deliverability: headroom and ramp capability
            if r[g, t] < -TOL or r[g, t] > pmax - p[g, t] + TOL or r[g, t] > ru + TOL:
                errors.append(f"reserve {g} t{t} r={r[g,t]} p={p[g,t]}")
        else:
            if p[g, t] > TOL:
                errors.append(f"off unit produces {g} t{t} p={p[g,t]}")
            if r[g, t] > TOL:
                errors.append(f"off unit reserves {g} t{t}")
            prod_cost += 0.0
    # startup/shutdown logic vs commitment
    for t in range(T):
        prev = on0 if t == 0 else u[g, t - 1]
        if su_ind[t] != int(u[g, t] > prev):
            errors.append(f"startup logic {g} t{t}")
        if sd_ind[t] != int(prev > u[g, t]):
            errors.append(f"shutdown logic {g} t{t}")
    # startup costs
    for t in range(T):
        if su_ind[t] == 1:
            dt = downtime_before(g, t)
            startup_cost_total += tier_cost(G, dt)
    # ramping
    prev_p, prev_u = p0, on0
    for t in range(T):
        if u[g, t] == 1 and prev_u == 1:
            if p[g, t] - prev_p > ru + TOL:
                errors.append(f"ramp up {g} t{t}")
            if prev_p - p[g, t] > rd + TOL:
                errors.append(f"ramp down {g} t{t}")
        if su_ind[t] == 1 and p[g, t] > su + TOL:
            errors.append(f"startup ramp {g} t{t} p={p[g,t]}")
        if sd_ind[t] == 1 and prev_p > sdn + TOL:
            errors.append(f"shutdown ramp {g} t{t} p={prev_p}")
        prev_p, prev_u = p[g, t], u[g, t]
    # min up / down
    for t in range(T):
        if su_ind[t] == 1:
            for i in range(t, min(t + utm, T)):
                if u[g, i] != 1:
                    errors.append(f"min up {g} start t{t} off at t{i}")
        if sd_ind[t] == 1:
            for i in range(t, min(t + dtm, T)):
                if u[g, i] != 0:
                    errors.append(f"min down {g} start t{t} on at t{i}")
    # initial conditions
    if on0 == 1 and up0 < utm:
        for t in range(min(utm - up0, T)):
            if u[g, t] != 1:
