                errors.append(f"reserve {g} t{t} r={r[g,t]} p={p[g,t]}")
        else:
            if p[g, t] > TOL:
                errors.append(f"off unit produces {g} t{t} p={p[g,t]}")
            if r[g, t] > TOL:
                errors.append(f"off unit reserves {g} t{t}")
            prod_cost += 0.0
    # startup/shutdown logic vs commitment
    for t in range(T):
        prev = on0 if t == 0 else u[g, t - 1]
        if su_ind[t] != int(u[g, t] > prev):
            errors.append(f"startup logic {g} t{t}")
        if sd_ind[t] != int(prev > u[g, t]):
            errors.append(f"shutdown logic {g} t{t}")
    # startup costs
    for t in range(T):
        if su_ind[t] == 1:
