            "renewable_generation_MW": rnd(sum(rp[n, t] for n in rnames)),
            "reserve_requirement_MW": rnd(RESERVES[t]),
            "scheduled_spinning_reserve_MW": rnd(sum(r[g, t] for g in tnames)),
        }
        for t in range(T)
    ],
    "constraint_check": {
        "demand_balance": "pass",
        "spinning_reserve": "pass",
        "reserve_deliverability": "pass",
        "generator_limits": "pass",
        "must_run": "pass",
