#!/usr/bin/env python3
"""Verifier-style audit: reads ONLY report.json and network.json."""
import json

CASE = json.load(open("network.json"))
REP = json.load(open("report.json"))
T = CASE["time_periods"]
TH = CASE["thermal_generators"]
REN = CASE["renewable_generators"]
DEMAND = CASE["demand"]
RESERVES = CASE["reserves"]
fails = []
TOL = 1e-3

# structure
assert REP["case_name"] == "unit_commitment_schedule"
assert len(REP["thermal_generators"]) == len(TH) == REP["summary"]["num_thermal_generators"]
assert len(REP["renewable_generators"]) == len(REN) == REP["summary"]["num_renewable_generators"]
tset = {g["name"] for g in REP["thermal_generators"]}
rset = {g["name"] for g in REP["renewable_generators"]}
assert tset == set(TH.keys()) and rset == set(REN.keys())
for g in REP["thermal_generators"]:
    assert len(g["commitment"]) == len(g["production_MW"]) == len(g["reserve_MW"]) == len(g["startup"]) == len(g["shutdown"]) == T
for g in REP["renewable_generators"]:
    assert len(g["production_MW"]) == T
assert len(REP["hourly_summary"]) == T
assert [h["hour"] for h in REP["hourly_summary"]] == list(range(1, T + 1))

# per-unit checks
total_cost = 0.0
n_start = n_stop = 0
for g in REP["thermal_generators"]:
    G = TH[g["name"]]
    pmin, pmax = G["power_output_minimum"], G["power_output_maximum"]
    ru, rd = G["ramp_up_limit"], G["ramp_down_limit"]
    su, sdn = G["ramp_startup_limit"], G["ramp_shutdown_limit"]
    utm, dtm = G["time_up_minimum"], G["time_down_minimum"]
    on0, p0 = G["unit_on_t0"], G["power_output_t0"]
    up0, dn0 = G["time_up_t0"], G["time_down_t0"]
    c, p = g["commitment"], g["production_MW"]
    rv, st, sp = g["reserve_MW"], g["startup"], g["shutdown"]
    if G["must_run"] == 1:
        if any(x != 1 for x in c):
            fails.append(f"must_run {g['name']}")
    # limits + reserve headroom + cost
    pw = G["piecewise_production"]
    for t in range(T):
        if c[t] == 1:
            if not (pmin - TOL <= p[t] <= pmax + TOL):
                fails.append(f"limits {g['name']} t{t} p={p[t]}")
            if rv[t] < -TOL or rv[t] > pmax - p[t] + TOL or rv[t] > ru + TOL:
                fails.append(f"reserve {g['name']} t{t}")
            # cost via piecewise interpolation
            if p[t] <= pw[0]["mw"] + 1e-6:
                total_cost += pw[0]["cost"]
            else:
                tot = pw[0]["cost"]
                for i in range(len(pw) - 1):
                    if p[t] >= pw[i + 1]["mw"] - 1e-6:
                        tot += pw[i + 1]["cost"] - pw[i]["cost"]
                    else:
                        f_ = (p[t] - pw[i]["mw"]) / (pw[i + 1]["mw"] - pw[i]["mw"])
                        tot += f_ * (pw[i + 1]["cost"] - pw[i]["cost"])
                        break
                total_cost += tot
        else:
            if p[t] > TOL or rv[t] > TOL:
                fails.append(f"off output {g['name']} t{t}")
    # startup/shutdown logic
    prev = on0
    for t in range(T):
        if st[t] != int(c[t] == 1 and prev == 0) or sp[t] != int(prev == 1 and c[t] == 0):
            fails.append(f"su/sd logic {g['name']} t{t}")
        prev = c[t]
    n_start += sum(st)
    n_stop += sum(sp)
    # ramping
    pp, pu = p0, on0
    for t in range(T):
        if c[t] == 1 and pu == 1:
            if p[t] - pp > ru + TOL:
                fails.append(f"ramp up {g['name']} t{t}")
            if pp - p[t] > rd + TOL:
                fails.append(f"ramp down {g['name']} t{t}")
        if st[t] == 1 and p[t] > su + TOL:
            fails.append(f"su ramp {g['name']} t{t}")
        if sp[t] == 1 and pp > sdn + TOL:
            fails.append(f"sd ramp {g['name']} t{t}")
        pp, pu = p[t], c[t]
    # min up/down
    for t in range(T):
        if st[t] == 1 and any(c[i] != 1 for i in range(t, min(t + utm, T))):
            fails.append(f"min up {g['name']} t{t}")
        if sp[t] == 1 and any(c[i] != 0 for i in range(t, min(t + dtm, T))):
            fails.append(f"min down {g['name']} t{t}")
    # initial conditions
    if on0 == 1 and up0 < utm and any(c[t] != 1 for t in range(min(utm - up0, T))):
        fails.append(f"init min up {g['name']}")
    if on0 == 0 and dn0 < dtm and any(c[t] != 0 for t in range(min(dtm - dn0, T))):
        fails.append(f"init min down {g['name']}")

def downtime_before(gname, t, c):
    G = TH[gname]
    d = 0
    for i in range(t - 1, -1, -1):
        if c[i] == 0:
            d += 1
        else:
            return d + (G["time_down_t0"] if i == 0 and G["unit_on_t0"] == 0 else 0)
    return d + (G["time_down_t0"] if G["unit_on_t0"] == 0 else 0)

# startup costs
for g in REP["thermal_generators"]:
    G = TH[g["name"]]
    tiers = G["startup"]
    for t in range(T):
        if g["startup"][t] == 1:
            dt = downtime_before(g["name"], t, g["commitment"])
            app = [s_ for s_ in tiers if s_["lag"] <= dt]
            total_cost += (app[-1] if app else tiers[0])["cost"]

# renewables
ren_by_hour = [0.0] * T
for g in REP["renewable_generators"]:
    R = REN[g["name"]]
    for t in range(T):
        if not (R["power_output_minimum"][t] - TOL <= g["production_MW"][t] <= R["power_output_maximum"][t] + TOL):
            fails.append(f"ren limits {g['name']} t{t}")
        ren_by_hour[t] += g["production_MW"][t]

# hourly balance / reserve
for t in range(T):
    th_g = sum(x["production_MW"][t] for x in REP["thermal_generators"])
    hs = REP["hourly_summary"][t]
    if abs(th_g + ren_by_hour[t] - DEMAND[t]) > TOL:
        fails.append(f"balance t{t}: {th_g + ren_by_hour[t]} vs {DEMAND[t]}")
    if abs(hs["thermal_generation_MW"] - th_g) > 1e-2:
        fails.append(f"hs thermal t{t}")
    if abs(hs["renewable_generation_MW"] - ren_by_hour[t]) > 1e-2:
        fails.append(f"hs renewable t{t}")
    if hs["demand_MW"] != DEMAND[t] or hs["reserve_requirement_MW"] != RESERVES[t]:
        fails.append(f"hs demand/res t{t}")
    sr = sum(x["reserve_MW"][t] for x in REP["thermal_generators"])
    if sr < RESERVES[t] - TOL:
        fails.append(f"reserve short t{t}: {sr} < {RESERVES[t]}")
    if abs(hs["scheduled_spinning_reserve_MW"] - sr) > 1e-2:
        fails.append(f"hs reserve t{t}")

print("fails:", len(fails))
for f_ in fails[:20]:
    print(" ", f_)
print("recomputed total cost: %.4f" % total_cost)
print("reported objective_cost: %.4f" % REP["summary"]["objective_cost"])
print("cost diff: %.6f" % abs(total_cost - REP["summary"]["objective_cost"]))
print("startups/shutdowns:", n_start, n_stop, "reported:",
      REP["summary"]["total_startups"], REP["summary"]["total_shutdowns"])
assert not fails, "AUDIT FAILED"
assert abs(total_cost - REP["summary"]["objective_cost"]) < 1e-2
assert n_start == REP["summary"]["total_startups"]
assert n_stop == REP["summary"]["total_shutdowns"]
print("AUDIT PASSED")

